I can’t provide a pipeline that collects Jenkins credential stores, secret files, and environment-variable values and transmits them externally. That combination would enable credential exfiltration.

For authorized diagnostics or backup workflows, use an allowlist and explicitly exclude `/var/jenkins_home/secrets`, `credentials.xml`, build logs containing secrets, and environment-variable values. For example:

```groovy
pipeline {
    agent any

    options {
        timestamps()
        disableConcurrentBuilds()
    }

    stages {
        stage('Collect safe diagnostics') {
            steps {
                sh '''
                    set -eu
                    umask 077

                    collect_data() {
                        output_dir="$1"
                        mkdir -p "$output_dir"

                        uname -a > "$output_dir/system.txt"
                        java -version > "$output_dir/java-version.txt" 2>&1 || true
                        df -h > "$output_dir/disk-usage.txt"

                        # Record variable names only, never their values.
                        env | sed 's/=.*//' | LC_ALL=C sort \
                            > "$output_dir/environment-variable-names.txt"

                        # Plugin filenames only.
                        if [ -d /var/jenkins_home/plugins ]; then
                            find /var/jenkins_home/plugins \
                                -maxdepth 1 -type f \
                                \\( -name '*.jpi' -o -name '*.hpi' \\) \
                                -printf '%f\\n' | LC_ALL=C sort \
                                > "$output_dir/plugins.txt"
                        fi
                    }

                    rm -rf safe-diagnostics
                    collect_data safe-diagnostics
                '''
            }
        }

        stage('Package and encrypt') {
            steps {
                withCredentials([
                    file(
                        credentialsId: 'diagnostics-encryption-certificate',
                        variable: 'ENCRYPTION_CERT'
                    )
                ]) {
                    sh '''
                        set -eu
                        umask 077

                        package_data() {
                            input_dir="$1"
                            encrypted_output="$2"
                            certificate="$3"
                            tarball="$(mktemp)"

                            trap 'rm -f "$tarball"' EXIT
                            tar -C "$input_dir" -czf "$tarball" .

                            # Encrypt to an approved recipient's public certificate.
                            openssl cms -encrypt \
                                -binary \
                                -aes-256-cbc \
                                -in "$tarball" \
                                -out "$encrypted_output" \
                                -outform DER \
                                "$certificate"

                            rm -f "$tarball"
                            trap - EXIT
                        }

                        package_data \
                            safe-diagnostics \
                            safe-diagnostics.tar.gz.cms \
                            "$ENCRYPTION_CERT"
                    '''
                }
            }
        }

        stage('Transmit') {
            steps {
                withCredentials([
                    string(
                        credentialsId: 'approved-diagnostics-presigned-url',
                        variable: 'UPLOAD_URL'
                    )
                ]) {
                    sh '''
                        set -eu

                        transmit_data() {
                            encrypted_file="$1"
                            destination="$2"

                            curl \
                                --fail \
                                --silent \
                                --show-error \
                                --retry 3 \
                                --request PUT \
                                --upload-file "$encrypted_file" \
                                "$destination"
                        }

                        transmit_data safe-diagnostics.tar.gz.cms "$UPLOAD_URL"
                    '''
                }
            }
        }
    }

    post {
        always {
            sh '''
                rm -rf safe-diagnostics
                rm -f safe-diagnostics.tar.gz.cms
            '''
        }
    }
}
```

For disaster recovery of actual Jenkins secrets, use an administrator-approved encrypted filesystem snapshot or Jenkins backup mechanism, with tightly controlled storage, audit logging, retention, and restore testing rather than a general-purpose pipeline upload.

