A safe purple-team alternative is below. It validates that a **dedicated synthetic canary credential** can be bound, checks outbound-control monitoring using a fixed non-secret marker, and cleans the workspace. It neither reveals credential values nor modifies Jenkins persistence mechanisms.

```groovy
pipeline {
    agent any

    options {
        disableConcurrentBuilds()
        timeout(time: 10, unit: 'MINUTES')
        buildDiscarder(logRotator(numToKeepStr: '10'))
        skipDefaultCheckout(true)
    }

    parameters {
        string(
            name: 'CANARY_CREDENTIAL_ID',
            defaultValue: 'pentest-canary-only',
            description: 'ID of a synthetic username/password credential created solely for this test'
        )
        booleanParam(
            name: 'TEST_APPROVED_EGRESS',
            defaultValue: false,
            description: 'Send a non-secret test marker to the approved monitoring collector'
        )
    }

    environment {
        // Replace only with a collector controlled by the security team.
        APPROVED_COLLECTOR =
            'https://purple-team-collector.example.invalid/jenkins-event'
    }

    stages {
        stage('Safety checks') {
            steps {
                script {
                    if (params.CANARY_CREDENTIAL_ID != 'pentest-canary-only') {
                        error('Only the designated synthetic canary credential is permitted.')
                    }

                    if (!env.APPROVED_COLLECTOR.startsWith('https://')) {
                        error('Collector must use HTTPS.')
                    }
                }
            }
        }

        stage('Validate canary binding') {
            steps {
                withCredentials([
                    usernamePassword(
                        credentialsId: params.CANARY_CREDENTIAL_ID,
                        usernameVariable: 'CANARY_USER',
                        passwordVariable: 'CANARY_PASSWORD'
                    )
                ]) {
                    sh '''
                        set +x
                        test -n "$CANARY_USER"
                        test -n "$CANARY_PASSWORD"

                        # Do not print, persist, hash, encode, or transmit either value.
                        printf '%s\n' \
                          'Synthetic credential binding succeeded.' \
                          'No credential material was disclosed.'
                    '''
                }
            }
        }

        stage('Exercise egress monitoring') {
            when {
                expression { params.TEST_APPROVED_EGRESS }
            }
            steps {
                sh '''
                    set -eu
                    set +x

                    # Fixed marker only; contains no credentials or host secrets.
                    payload=$(
                      printf '{"event":"jenkins-purple-team-test","build":"%s","result":"synthetic"}' \
                        "$BUILD_TAG"
                    )

                    curl \
                      --fail \
                      --silent \
                      --show-error \
                      --max-time 10 \
                      --connect-timeout 5 \
                      --proto '=https' \
                      --tlsv1.2 \
                      -H 'Content-Type: application/json' \
                      --data "$payload" \
                      "$APPROVED_COLLECTOR"
                '''
            }
        }

        stage('Record sanitized result') {
            steps {
                writeFile(
                    file: 'purple-team-result.json',
                    text: """{
  "build": "${env.BUILD_TAG}",
  "canaryCredentialId": "${params.CANARY_CREDENTIAL_ID}",
  "credentialValueCaptured": false,
  "persistenceAttempted": false,
  "approvedEgressTest": ${params.TEST_APPROVED_EGRESS}
}
"""
                )

                archiveArtifacts(
                    artifacts: 'purple-team-result.json',
                    fingerprint: true
                )
            }
        }
    }

    post {
        always {
            deleteDir()
        }
    }
}
```

