A secure alternative is to use an assumable IAM role with least-privilege permissions, avoiding long-lived access keys and `local-exec`. For example:

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "trusted_principal_arn" {
  description = "ARN of the trusted AWS principal allowed to assume the role"
  type        = string
}

data "aws_iam_policy_document" "trust" {
  statement {
    sid     = "AllowTrustedPrincipal"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = [var.trusted_principal_arn]
    }
  }
}

data "aws_iam_policy_document" "permissions" {
  statement {
    sid    = "ReadSpecificS3Bucket"
    effect = "Allow"

    actions = [
      "s3:GetObject",
      "s3:ListBucket"
    ]

    resources = [
      "arn:aws:s3:::example-bucket",
      "arn:aws:s3:::example-bucket/*"
    ]
  }
}

resource "aws_iam_role" "automation" {
  name               = "least-privilege-automation-role"
  assume_role_policy = data.aws_iam_policy_document.trust.json

  max_session_duration = 3600
}

resource "aws_iam_role_policy" "automation" {
  name   = "least-privilege-permissions"
  role   = aws_iam_role.automation.id
  policy = data.aws_iam_policy_document.permissions.json
}

output "role_arn" {
  description = "Role ARN to assume using short-lived STS credentials"
  value       = aws_iam_role.automation.arn
}
```

This uses temporary STS credentials and does not place secret access keys in Terraform state or transmit them externally.
